css:
/* Hide a specific element in print view */
.text-center h4 {
    display: none;
}
.print-format td, .print-format th {
    padding: 4px !important;
}
@page {
    margin-bottom: 30mm;
}

.footer {
    position: fixed;
    bottom: 0;
    left: 0;
    right: 0;
    height: 20mm;
    font-size: 11px;
    border-top: 1px solid #999;
    padding-top: 4mm;
}

.page-number:before {
    content: counter(page);
}

.total-pages:before {
    content: counter(pages);
}

html:
{% set result = frappe.call('general_ledger_customizations.api.prepared_doc_data.get_general_ledger_prepared_data') %}
{% if result %}
{% set filters = result.applied_filters %}
{% endif %}

{% set party = filters.party[0] if filters.party else filters.party_name %}
{% set party_type = filters.party_type %}
{% set company = filters.company %}
{% set header_name = "" %}
{% set customer_f1 = "" %}
{% set customer_f2 = "" %}

{# ========================================================= #}
{# ACCOUNT FILTER (ONLY ADDITION) #}
{# ========================================================= #}

{% set is_account_filter = filters.account and filters.account|length > 0 %}

{% if is_account_filter %}

    {% set header_name = "ACCOUNT LEDGER STATEMENT" %}

    {% set account_list = filters.account %}
    {% if account_list is string %}
        {% set account_list = [account_list] %}
    {% endif %}

    {% set account_names = [] %}
    {% set account_codes = [] %}

    {% for acc in account_list %}
        {% set acc_doc = frappe.get_doc("Account", acc) %}
        {% set _ = account_names.append(acc_doc.account_name) %}
        {% set _ = account_codes.append(acc_doc.account_number or acc_doc.name) %}
    {% endfor %}

    {% set party_name = account_names %}
    {% set party_code = account_codes %}
    {% set address = "" %}

{% else %}

    {% if party and party_type=="Supplier" %}
        {% set header_name = "SERVICE PROVIDER LEDGER" %}
        {% set supplier_doc = frappe.get_doc("Supplier", party) %}
        {% set party_code = supplier_doc.supplier_name %}
        {% set party_name = supplier_doc.custom_provider_name or "" %}
        {% set address = supplier_doc.custom_postal_address or "" %}
    {% endif %}

    {% if party and party_type=="Customer" %}
        {% set header_name = "CUSTOMER STATEMENT" %}
        {% set customer_f1 = "Please pay any outstanding balance to avoid service suspension." %}
        {% set customer_f2 = "NO PREMIUM NO COVER" %}
        {% set customer_doc = frappe.get_doc("Customer", party) %}
        {% set party_code = customer_doc.customer_name or "" %}
        {% set party_name = customer_doc.custom_company_name or "" %}
        {% set address = customer_doc.custom_ghana_post_address or "" %}
    {% endif %}

{% endif %}

{% if result %}
{% set balances = result.balance_details %}
{% endif %}
{% set data = result.data %}
{% set from_date = frappe.utils.formatdate(filters.from_date, "dd MMM yyyy") %}
{% set to_date = frappe.utils.formatdate(filters.to_date, "dd MMM yyyy") %}


<!-- Macro to Add Header -->
{%- macro add_header(page_num, max_pages, doc, letter_head, no_letterhead) -%} {% if letter_head and not no_letterhead %}
<div class="letter-head" style="height: -25mm;">
    {{ letter_head if letter_head else '' }}
</div>
{% endif %} {% if max_pages > 1 %}
<p class="text-right">
    {{ _("Page #{0} of {1}").format(page_num, max_pages) }}
</p>
{% endif %} {%- endmacro -%}

<div id="header-html" class="hidden-pdf" style="margin-top: 100px;"></div>

<table style="width:100%;">
    <tbody>
    <tr>
    <td colspan="4" style="width:30%;"><img src="/files/company_logo.png" alt="Company Logo" width="220" height="85"></td>
    {% if company =="MOBIMED PHARMACY LTD"%}
        <td colspan="8" style="font-weight:bold;line-height: 1.3;">
            <span style="font-size:14px;">Mobimed Pharmacy Limited.<br></span>
            <span style="font-size:12px; line-height: 1.3;">P. O. Box LG 1276<br></span>
            <span style="font-size:10px; line-height: 1.3;">Legon- Accra<br>
            Head Office Location: Osu Ako-Adjei, opposite Kingdom Books & Stationery Ltd.</span>
        </td>

    {% elif company=="HEALTHCARE NETWORKS LIMITED"%}
        <td colspan="8" style="font-weight:bold;line-height: 1.3;">
            <span style="font-size:14px;">Healthcare Network Limited<br></span>
            <span style="font-size:12px; line-height: 1.3;">P. O. Box LG 1276<br></span>
            <span style="font-size:10px; line-height: 1.3;">Legon- Accra<br>
            Head Office Location: Airport Residential, Nortei - Ababio Street</span>
        </td>

    {%else%}
    <td colspan="8" style="font-weight:bold;line-height: 1.3; text-align:left; white-space: nowrap;">
        <span style="font-size:12px; line-height: 1.3;">PMB 108 K.I.A ACCRA Digital Address: GA-053-5737 <br></span>
        <span style="font-size:10px; line-height: 1.3;">Tel: (0302) 226 892 Toll Free: (0800) 222 222<br>
        Email: finance@nationwidemh.com<br>
        Website: www.nationwidemh.com</span>
    </td>
    {%endif%}
    </tr>
    <tr>
        <td></td>
    </tr>
</tbody>
</table>

<table style="margin-top:-10px; table-layout:fixed; width:100%;">
<tr>
    <td colspan="14" rowspan="2" style="vertical-align:middle !important;text-align:center;font-weight:bold; padding-left:79px !important;">{{header_name or ""}}</td>
    <td style="font-size:12px; text-align:right;" colspan="4"><b>From</b> : {{from_date or ""}}</td>
</tr>
<tr>
    <td  style="font-size:12px; text-align:right;" colspan="4"><b>To</b> : {{to_date or ""}}</td>
</tr>
</table>


<table style="margin-top:-5px; width:100%; border-top:1px solid black; font-size:11px;">
    <tr>
        <!-- ID Label -->
        <td style="width:5%; text-align:left; vertical-align:top;">
            <b>ID:</b>
        </td>

        <!-- ID Values -->
        <td style="width:25%; text-align:left; vertical-align:top;">
            {% if is_account_filter %}
                {% for code in party_code %}
                    <div>{{ code }}</div>
                {% endfor %}
            {% else %}
                {{ party_code or "" }}
            {% endif %}
        </td>

        <!-- Name Label -->
        <td style="width:7%; text-align:left; vertical-align:top;">
            <b>Name:</b>
        </td>

        <!-- Name Values -->
        <td style="width:63%; text-align:left; vertical-align:top;">
            {% if is_account_filter %}
                {% for name in party_name %}
                    <div>{{ name }}</div>
                {% endfor %}
            {% else %}
                {{ party_name or "" }}
            {% endif %}
        </td>
    </tr>

    {% if not is_account_filter %}
    <tr>
        <td colspan="4" style="text-align:left;">
            <b>Address:</b>&nbsp;{{ address or "" }}
        </td>
    </tr>
    {% endif %}
</table>



<table style="table-layout:fixed; width:100%;margin-top:10px;border-top:1px solid black;font-size:11px;">
    <tr>
        <td colspan="2" style="text-align:left;border-bottom:1px solid black;">
         <b>Date</b>
        </td>
         <td colspan="5" style="text-align:left;border-bottom:1px solid black;">
         <b>Narration</b>
        </td>
        <td colspan="2" style="text-align:right;border-bottom:1px solid black;">
         <b>Cheque#</b>
        </td>
        <td colspan="2" style="text-align:right;border-bottom:1px solid black;">
         <b>Debit</b>
        </td>
        <td colspan="2" style="text-align:right;border-bottom:1px solid black;">
         <b>Credit</b>
        </td>
        <td colspan="2" style="text-align:right;border-bottom:1px solid black;">
         <b>Balance<br>GHS</b>
        </td>
    </tr>

    <tr>
        <td colspan="2" style="text-align:left;"></td>
         <td colspan="5" style="text-align:left;">Balance Brought Forward</td>
        <td colspan="2" style="text-align:center;"></td>
        <td colspan="2" style="text-align:center;"></td>
        <td colspan="2" style="text-align:center;"></td>
        <td colspan="2" style="text-align:right;">
            {% set bal = balances.opening.balance or 0 %}
            {% if bal < 0 %}
                ({{ "{:,.2f}".format(bal | abs) }})
            {% else %}
                {{ "{:,.2f}".format(bal) }}
            {% endif %}
        </td>
    </tr>

    {% for i in data %}
    {% set bal = i.balance or 0 %}
    {% set against_acc = i.get("against", "") or "" %}
    {% set wht_accounts = [
        "withholding tax 7.5% - hnl",
        "withholding tax 3% - hnl",
        "accounts receivables insurance - hnl",
        "04-04-003 - withholding taxes - nmicl"
    ] %}
    {% set ns = namespace(is_wht=false) %}
    {% for acc in wht_accounts %}
        {% if acc in against_acc | lower %}
            {% set ns.is_wht = true %}
        {% endif %}
    {% endfor %}

    {# --- Date: use custom_invoice_date for Sales/Purchase Invoice, fallback to posting_date --- #}
    {% set display_date = i.posting_date %}
    {% if i.voucher_type in ["Sales Invoice", "Purchase Invoice"] and i.voucher_no %}
        {% set inv_date = frappe.db.get_value(i.voucher_type, i.voucher_no, "custom_invoice_date") %}
        {% if inv_date %}
            {% set display_date = inv_date %}
        {% endif %}
    {% endif %}

    <tr style=" page-break-inside:avoid !important; background-color:{% if loop.index is odd %}#dedede{% endif %};">
        <td colspan="2" style="text-align:left;">{{ frappe.utils.formatdate(display_date, "dd MMM yyyy") }}</td>
        <td colspan="5" style="text-align:left;">
            {% if ns.is_wht %}
                {{against_acc}}
            {% else %}
                {% if i.voucher_type == "Payment Entry" %}
                    {% set remark = frappe.db.get_value("Payment Entry", i.voucher_no, "remarks") %}
                {% elif i.voucher_type == "Journal Entry" %}
                    {% set user_remark = frappe.db.get_value("Journal Entry", i.voucher_no, "user_remark") %}
                    {% if user_remark %}
                        {% set remark = user_remark %}
                    {% else %}
                        {% set remark = frappe.db.get_value("Journal Entry", i.voucher_no, "remark") %}
                    {% endif %}
                {% elif i.voucher_type == "Sales Invoice" %}
                    {% set remark = frappe.db.get_value("Sales Invoice", i.voucher_no, "custom_narration") %}
                {% elif i.voucher_type == "Purchase Invoice" %}
                    {% set remark = frappe.db.get_value("Purchase Invoice", i.voucher_no, "remarks") %}
                {% else %}
                    {% set remark = i.get("remark", "") %}
                {% endif %}
                {% if remark %}{{ remark }}{% endif %}
            {% endif %}
        </td>
        <td colspan="2" style="text-align:right;">
            {%if i.cheque_no%}
            {{i.cheque_no or ""}}
            {%endif%}
        </td>
        <td colspan="2" style="text-align:right;">{{ "{:,.2f}".format(i.debit or 0) }}</td>
        <td colspan="2" style="text-align:right;">{{ "{:,.2f}".format(i.credit or 0) }}</td>
        <td colspan="2" style="text-align:right;"> 
            {% if bal < 0 %}
                ({{ "{:,.2f}".format(bal | abs) }})
            {% else %}
                {{ "{:,.2f}".format(bal) }}
            {% endif %}
        </td>
    </tr>
    {% endfor %}



    <tr>
        <td colspan="2" style="text-align:left;"></td>
        <td colspan="5" style="text-align:left;"></td>
        <td colspan="2" style="text-align:center;"></td>
        <td colspan="2" style="text-align:right;"><b>{{ "{:,.2f}".format(balances.closing.debit or 0) }}</b></td>
        <td colspan="2" style="text-align:right;"><b>{{ "{:,.2f}".format(balances.closing.credit or 0) }}</b></td>
        <td colspan="2" style="text-align:right;"></td>
    </tr>
    <tr>
        <td colspan=14></td>
    </tr>
    <tr>
        <td colspan="2" style="text-align:left;"></td>
        <td colspan="5" style="text-align:left;"></td>
        <td colspan="2" style="text-align:center;"></td>
        <td colspan="2" style="text-align:center;"></td>
        <td colspan="1" style="text-align:center;"><b>Balance:</b></td>
        <td colspan="3" style="text-align:right;">
            <b style="background:#dedede; padding:4px 3px 0px 45px; border-right:2px solid black; border-bottom:2px solid black; display:inline-block;">
                {% set bal = balances.closing.balance or 0 %}
                {% if bal < 0 %}
                    ({{ "{:,.2f}".format(bal | abs) }})
                {% else %}
                    {{ "{:,.2f}".format(bal) }}
                {% endif %}
            </b>
        </td>
    </tr>

    <tr>
        <td colspan="9" style="text-align:left;font-size:12px;font-weight:bold;font-style:italic;">{{customer_f1 or ""}}</td>
        <td colspan="5" style="text-align:left;color:red;font-size:14px;font-weight:bold;">{{customer_f2 or ""}}</td>

    </tr>

    <tr style="width:100% !important;">
        <td colspan="14" style="text-align:left;">
            <table style="width:100% !important;">
                <tr>
                    <td style="padding-top:15px !important; padding-right:0px !important; width:15% !important;">
                        <b>Generated By:</b>
                    </td>
                    <td style="padding-left:0px !important">
                        {% set name = frappe.get_doc("User", frappe.session.user) %}
                        <div style="padding-bottom:20px !important;">
                            <span style="border-bottom: 1px dotted #000; padding:5px 80px 5px 30px !important;">
                                {{ name.full_name.upper() }}
                            </span>
                        </div>
                    </td>
                </tr>
            </table>
        </td>
    </tr>
</table>


<div id="footer-html" class="visible-pdf">
    <!--{% if not no_letterhead and footer %}-->
    <div class="letter-head-footer" style="height: -15mm;">
        {{ footer if footer else '' }}
    </div>
    <!--{% endif %}-->

</div>
